/// Widget logo Classly (ikon bola lampu-otak di dalam huruf "C").
/// Gunakan [size] untuk mengatur lebar logo; tingginya menyesuaikan
/// otomatis (aspect ratio asli logo dipertahankan).
class ClasslyLogo extends StatelessWidget {
  final double size;
  final BoxFit fit;

  const ClasslyLogo({super.key, this.size = 48, this.fit = BoxFit.contain});

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_kClasslyLogoBase64),
      width: size,
      fit: fit,
      filterQuality: FilterQuality.high,
    );
  }
}
